// Seva shop installer. Run from the repo root or the apps\web folder:  node install-seva-shop.mjs
// Writes the seva list/detail/cart/checkout/payment/confirmation files and updates en.json + ta.json.
// Existing files are copied to <name>.bak before being replaced.
import fs from 'node:fs';
import path from 'node:path';

let root = process.argv[2] ? path.resolve(process.argv[2]) : process.cwd();
const isWeb = (d) => fs.existsSync(path.join(d, 'src', 'dictionaries', 'en.json'));
// Allow running from the repo root: use apps\\web when found
if (!isWeb(root) && isWeb(path.join(root, 'apps', 'web'))) root = path.join(root, 'apps', 'web');
if (!isWeb(root)) {
  console.error('Could not find src\\dictionaries\\en.json in ' + root + '. Run this from the repo root or from apps\\web.');
  process.exit(1);
}
console.log('Installing into ' + root + '\n');

const FILES = {"src/lib/format.ts":"import type { Locale } from './i18n';\n\nconst MONTHS: Record<Locale, string[]> = {\n  en: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],\n  ta: ['ஜன', 'பிப்', 'மார்', 'ஏப்', 'மே', 'ஜூன்', 'ஜூலை', 'ஆக', 'செப்', 'அக்', 'நவ', 'டிச'],\n};\n\nexport const WEEKDAYS: Record<Locale, string[]> = {\n  en: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],\n  ta: ['ஞாயிற்றுக்கிழமை', 'திங்கட்கிழமை', 'செவ்வாய்க்கிழமை', 'புதன்கிழமை', 'வியாழக்கிழமை', 'வெள்ளிக்கிழமை', 'சனிக்கிழமை'],\n};\n\n// 12345 -> \"₹12,345\"\nexport const rupees = (n: number) => `₹${new Intl.NumberFormat('en-IN').format(n)}`;\n\n// \"2026-10-25\" -> \"25 Oct 2026\". Done by hand so the server and the browser always print the same text.\nexport function formatDate(iso: string, locale: Locale) {\n  const [y, m, d] = iso.split('-').map(Number);\n  return `${d} ${MONTHS[locale][m - 1]} ${y}`;\n}\n\n// Today as \"YYYY-MM-DD\" in the visitor's own time zone\nexport function todayISO() {\n  const d = new Date();\n  const mm = String(d.getMonth() + 1).padStart(2, '0');\n  const dd = String(d.getDate()).padStart(2, '0');\n  return `${d.getFullYear()}-${mm}-${dd}`;\n}\n\n// \"2026-10-25\" -> 0..6 (Sunday = 0)\nexport const weekdayOf = (iso: string) => {\n  const [y, m, d] = iso.split('-').map(Number);\n  return new Date(y, m - 1, d).getDay();\n};\n\n// Seva photo: /images/sevas/<slug>.jpg, with a gradient until the photo exists\nconst FALLBACK = 'linear-gradient(135deg, #7A1C1C 0%, #D97706 140%)';\nexport const sevaPhoto = (slug: string) => `url('/images/sevas/${slug}.jpg'), ${FALLBACK}`;\n","src/data/sevas.ts":"// DUMMY DATA. The CMS portal will replace this file: keep the shape, swap the source.\n// Every text has an English and a Tamil version. `amount: 0` means \"as per the devotee's ability\".\n\nimport type { Locale } from '@/lib/i18n';\n\nexport type L = { en: string; ta: string };\nexport type SevaKind = 'festival' | 'regular' | 'annadhanam';\n\nexport type Seva = {\n  slug: string;\n  kind: SevaKind;\n  name: L;\n  when: L;                 // shown on cards and on the detail page\n  amount: number;          // fixed amount in rupees; 0 = devotee chooses\n  minAmount: number;       // lowest amount a devotee may choose (only when amount is 0)\n  from?: string;           // first date the seva can be booked for (YYYY-MM-DD)\n  to?: string;             // last date (same as `from` for a one-day seva)\n  weekday?: number;        // 0 = Sunday ... 6 = Saturday: seva is offered only on this day\n  note?: L;                // extra line shown under the date\n  status: 'open' | 'closed';\n  maxQty: number;\n  description: { en: string[]; ta: string[] }; // paragraphs; empty until the ashram writes them\n  includes: { label: L; price: number }[];     // itemised list, if any\n};\n\nconst base = { minAmount: 1, status: 'open' as const, maxQty: 10, description: { en: [], ta: [] }, includes: [] };\n\nexport const SEVAS: Seva[] = [\n  { ...base, slug: 'kasi-viswanathar-annabishekam', kind: 'festival', amount: 0, from: '2026-10-25', to: '2026-10-25',\n    name: { en: 'Sri Kasi Viswanathar Annabishekam', ta: 'ஸ்ரீ காசி விஸ்வநாதர் அன்னாபிஷேகம்' },\n    when: { en: '25 Oct 2026', ta: '25 அக் 2026' } },\n  { ...base, slug: 'skanda-shashti-puja', kind: 'festival', amount: 0, from: '2026-11-15', to: '2026-11-15',\n    name: { en: 'Sri Skanda Shashti Puja', ta: 'ஸ்ரீ ஸ்கந்த சஷ்டி பூஜை' },\n    when: { en: '15 Nov 2026', ta: '15 நவ 2026' } },\n  { ...base, slug: 'navaratri-one-day-puja-kanikai', kind: 'festival', amount: 10001, from: '2026-10-11', to: '2026-10-21',\n    name: { en: 'Sri Saradha Navaratri One Day Puja Kanikai', ta: 'ஸ்ரீ சாரதா நவராத்திரி ஒரு நாள் பூஜை காணிக்கை' },\n    when: { en: '11 – 21 Oct 2026', ta: '11 – 21 அக் 2026' } },\n  { ...base, slug: 'navaratri-sumangali-puja', kind: 'festival', amount: 2500, from: '2026-10-11', to: '2026-10-21',\n    name: { en: 'Sri Saradha Navaratri Sumangali Puja', ta: 'ஸ்ரீ சாரதா நவராத்திரி சுமங்கலி பூஜை' },\n    when: { en: '11 – 21 Oct 2026', ta: '11 – 21 அக் 2026' } },\n  { ...base, slug: 'navaratri-sankalpam', kind: 'festival', amount: 501, from: '2026-10-11', to: '2026-10-21',\n    name: { en: 'Sri Saradha Navaratri Sankalpam', ta: 'ஸ்ரீ சாரதா நவராத்திரி சங்கல்பம்' },\n    when: { en: '11 – 21 Oct 2026', ta: '11 – 21 அக் 2026' } },\n  { ...base, slug: 'navaratri-2026', kind: 'festival', amount: 0, from: '2026-10-11', to: '2026-10-21',\n    name: { en: 'Sri Saradha Navaratri 2026', ta: 'ஸ்ரீ சாரதா நவராத்திரி 2026' },\n    when: { en: '11 – 21 Oct 2026', ta: '11 – 21 அக் 2026' },\n    includes: [\n      { label: { en: 'Homa materials', ta: 'ஹோம பொருட்கள்' }, price: 20000 },\n      { label: { en: 'Ghee, 20 kg', ta: 'நெய், 20 கிலோ' }, price: 15000 },\n      { label: { en: 'Thirumangalyam (2 gram gold)', ta: 'திருமாங்கல்யம் (2 கிராம் தங்கம்)' }, price: 35000 },\n      { label: { en: 'Flowers and garlands', ta: 'பூக்களும் மாலைகளும்' }, price: 15000 },\n      { label: { en: 'Vastra samarpanam for Sri Mangala Chandi Homam', ta: 'ஸ்ரீ மங்கள சண்டி ஹோமத்துக்கு வஸ்திர சமர்ப்பணம்' }, price: 10000 },\n      { label: { en: 'Sivacharyar sambavanai and Saptasati parayana ritvik sambavanai', ta: 'சிவாச்சாரியார் சம்பாவனை மற்றும் சப்தசதி பாராயண ரித்விக் சம்பாவனை' }, price: 90000 },\n      { label: { en: 'Homa Sankalpam', ta: 'ஹோம சங்கல்பம்' }, price: 501 },\n    ] },\n  { ...base, slug: 'go-puja', kind: 'regular', amount: 200,\n    name: { en: 'Go Puja', ta: 'கோபூஜை' }, when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n  { ...base, slug: 'archanai', kind: 'regular', amount: 200,\n    name: { en: 'Archanai', ta: 'அர்ச்சனை' }, when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n  { ...base, slug: 'special-puja', kind: 'regular', amount: 500,\n    name: { en: 'Special Puja (birthday, wedding day, etc.)', ta: 'சிறப்பு பூஜை (பிறந்தநாள், திருமண நாள் போன்றவை)' },\n    when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n  { ...base, slug: 'ganga-puja', kind: 'regular', amount: 200, weekday: 5,\n    name: { en: 'Sri Ganga Puja (Aarti)', ta: 'ஸ்ரீ கங்கா பூஜை (ஆரத்தி)' },\n    when: { en: 'Every Friday', ta: 'ஒவ்வொரு வெள்ளிக்கிழமை' } },\n  { ...base, slug: 'pradosa-puja', kind: 'regular', amount: 200,\n    name: { en: 'Sri Pradosa Puja', ta: 'ஸ்ரீ பிரதோஷ கால பூஜை' },\n    when: { en: 'Only on Triyodasi', ta: 'திரயோதசி அன்று மட்டும்' },\n    note: { en: 'Offered only on Triyodasi. Please choose a Triyodasi date; the ashram will confirm it.', ta: 'திரயோதசி அன்று மட்டும் நடைபெறும். திரயோதசி தேதியைத் தேர்ந்தெடுக்கவும்; ஆசிரமம் உறுதிப்படுத்தும்.' } },\n  { ...base, slug: 'special-abhishekam', kind: 'regular', amount: 2000,\n    name: { en: 'Special Abhishekam and Alankaram', ta: 'சிறப்பு அபிஷேகம் & அலங்காரம்' },\n    when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n  { ...base, slug: 'udayastamana-puja', kind: 'regular', amount: 5000,\n    name: { en: 'Udayastamana Puja', ta: 'உதயாஸ்தமன பூஜை' }, when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n  { ...base, slug: 'parivara-devata-puja', kind: 'regular', amount: 1000,\n    name: { en: 'Sri Parivara Devata Puja', ta: 'ஸ்ரீ பரிவார தேவதா பூஜை' }, when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n  { ...base, slug: 'annadhanam', kind: 'annadhanam', amount: 9000, weekday: 4,\n    name: { en: 'Annadhanam', ta: 'அன்னதானம்' },\n    when: { en: 'Every Thursday', ta: 'ஒவ்வொரு வியாழக்கிழமை' } },\n];\n\nexport const getSeva = (slug: string) => SEVAS.find((s) => s.slug === slug);\nexport const txt = (l: L, locale: Locale) => l[locale];\n\n// How the date for a seva is chosen\nexport type DateMode = 'fixed' | 'range' | 'weekday' | 'any';\nexport function dateMode(s: Seva): DateMode {\n  if (s.from && s.from === s.to) return 'fixed';\n  if (s.from && s.to) return 'range';\n  if (s.weekday !== undefined) return 'weekday';\n  return 'any';\n}\n","src/components/SevaList.tsx":"'use client';\n\nimport { useMemo, useState } from 'react';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { SEVAS, txt } from '@/data/sevas';\nimport SevaCard from './sevas/SevaCard';\n\ntype T = Dictionary['sevas'];\n\n// Search, filter and sort over the seva catalogue. Each card opens its own detail page.\nexport default function SevaList({ t, locale }: { t: T; locale: Locale }) {\n  const [filter, setFilter] = useState('all');\n  const [query, setQuery] = useState('');\n  const [sort, setSort] = useState('default');\n\n  const shown = useMemo(() => {\n    const q = query.trim().toLowerCase();\n    const list = SEVAS.filter((s) => (filter === 'all' || s.kind === filter) && (!q || txt(s.name, locale).toLowerCase().includes(q)));\n    if (sort === 'low') return [...list].sort((a, b) => (a.amount || Infinity) - (b.amount || Infinity));\n    if (sort === 'high') return [...list].sort((a, b) => b.amount - a.amount);\n    return list;\n  }, [filter, query, sort, locale]);\n\n  const reset = () => {\n    setFilter('all');\n    setQuery('');\n    setSort('default');\n  };\n\n  return (\n    <div id=\"seva-list\" className=\"scroll-mt-24\">\n      {/* Filters */}\n      <div role=\"group\" aria-label={t.filterLabel} className=\"flex flex-wrap justify-center gap-3\">\n        {t.filters.map((f) => {\n          const on = filter === f.key;\n          const count = f.key === 'all' ? SEVAS.length : SEVAS.filter((s) => s.kind === f.key).length;\n          return (\n            <button\n              key={f.key}\n              type=\"button\"\n              aria-pressed={on}\n              onClick={() => setFilter(f.key)}\n              className={`rounded-full px-5 py-2 text-sm font-semibold ring-1 transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron ${\n                on ? 'bg-maroon text-white ring-maroon' : 'bg-white text-maroon ring-saffron/60 hover:bg-rose'\n              }`}\n            >\n              {f.label} <span className={on ? 'text-rose' : 'text-charcoal/60'}>({count})</span>\n            </button>\n          );\n        })}\n      </div>\n\n      {/* Search and sort */}\n      <div className=\"mx-auto mt-6 grid max-w-3xl gap-3 sm:grid-cols-[1fr_220px]\">\n        <label className=\"block\">\n          <span className=\"sr-only\">{t.searchLabel}</span>\n          <input\n            type=\"search\"\n            value={query}\n            onChange={(e) => setQuery(e.target.value)}\n            placeholder={t.searchPlaceholder}\n            className=\"w-full rounded-md border-2 border-rose bg-white px-4 py-2.5 text-charcoal placeholder:text-charcoal/50 focus:border-saffron focus:outline-none\"\n          />\n        </label>\n        <label className=\"block\">\n          <span className=\"sr-only\">{t.sortLabel}</span>\n          <select\n            value={sort}\n            onChange={(e) => setSort(e.target.value)}\n            className=\"w-full rounded-md border-2 border-rose bg-white px-3 py-2.5 text-charcoal focus:border-saffron focus:outline-none\"\n          >\n            {t.sortOptions.map((o) => (\n              <option key={o.key} value={o.key}>{o.label}</option>\n            ))}\n          </select>\n        </label>\n      </div>\n\n      <p role=\"status\" className=\"mt-6 text-center text-sm font-semibold text-charcoal/70\">{t.countLabel.replace('{n}', String(shown.length))}</p>\n\n      {/* Cards */}\n      {shown.length > 0 ? (\n        <ul className=\"mt-6 grid gap-6 sm:grid-cols-2 lg:grid-cols-3\">\n          {shown.map((s) => (\n            <li key={s.slug} className=\"h-full\">\n              <SevaCard seva={s} locale={locale} t={t} />\n            </li>\n          ))}\n        </ul>\n      ) : (\n        <div className=\"mt-8 rounded-2xl bg-rose/50 px-6 py-12 text-center\">\n          <p className=\"font-serif text-lg text-charcoal\">{t.noResults}</p>\n          <button type=\"button\" onClick={reset} className=\"mt-4 rounded-md bg-maroon px-5 py-2.5 font-semibold text-white hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">\n            {t.clearFilters}\n          </button>\n        </div>\n      )}\n    </div>\n  );\n}\n","src/components/Header.tsx":"'use client';\n\nimport Link from 'next/link';\nimport { usePathname } from 'next/navigation';\nimport { useEffect, useRef, useState } from 'react';\nimport { NAV } from '@/lib/nav';\nimport { locales, type Locale } from '@/lib/i18n';\nimport type { Dictionary } from '@/lib/dictionary';\nimport CartLink from '@/components/cart/CartLink';\n\ntype Props = {\n  locale: Locale;\n  siteName: string;\n  tagline: string;\n  labels: Dictionary['nav'];\n  a11y: Dictionary['a11y'];\n  cartLabel: string;\n};\n\nconst LANG_LABEL: Record<Locale, string> = { en: 'EN', ta: 'தமிழ்' };\n\n// \"/ta/audio\" -> \"/audio\", \"/en\" -> \"/\"\nconst stripLocale = (p: string) => p.replace(/^\\/(en|ta)(?=\\/|$)/, '') || '/';\n\nfunction Chevron({ open }: { open: boolean }) {\n  return (\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\"\n      strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\"\n      className={`transition-transform ${open ? 'rotate-180' : ''}`}>\n      <path d=\"M6 9l6 6 6-6\" />\n    </svg>\n  );\n}\n\nexport default function Header({ locale, siteName, tagline, labels, a11y, cartLabel }: Props) {\n  const pathname = usePathname();\n  const path = stripLocale(pathname);\n\n  const [mobileOpen, setMobileOpen] = useState(false); // hamburger panel\n  const [dropdown, setDropdown] = useState(false);     // desktop \"Discourses\" menu\n  const [mobileSub, setMobileSub] = useState(false);   // mobile \"Discourses\" accordion\n  const dropdownRef = useRef<HTMLLIElement>(null);\n\n  const href = (h: string) => `/${locale}${h}`;\n  const isActive = (h: string) => (h === '' ? path === '/' : path === h || path.startsWith(`${h}/`));\n\n  // Close every menu after navigating to another page\n  useEffect(() => {\n    setMobileOpen(false);\n    setDropdown(false);\n    setMobileSub(false);\n  }, [pathname]);\n\n  // Desktop dropdown: close on outside click or Escape\n  useEffect(() => {\n    if (!dropdown) return;\n    const onDown = (e: MouseEvent) => {\n      if (!dropdownRef.current?.contains(e.target as Node)) setDropdown(false);\n    };\n    const onKey = (e: KeyboardEvent) => {\n      if (e.key === 'Escape') setDropdown(false);\n    };\n    document.addEventListener('mousedown', onDown);\n    document.addEventListener('keydown', onKey);\n    return () => {\n      document.removeEventListener('mousedown', onDown);\n      document.removeEventListener('keydown', onKey);\n    };\n  }, [dropdown]);\n\n  const linkBase = 'inline-flex items-center whitespace-nowrap border-b-2 px-3 py-2 text-[15px] font-medium transition-colors';\n  const linkClass = (active: boolean) =>\n    `${linkBase} ${active ? 'border-saffron text-maroon' : 'border-transparent text-charcoal hover:text-maroon'}`;\n\n  // EN | தமிழ் switch: same page, other language\n  const languageSwitch = (\n    <div role=\"group\" aria-label={a11y.language}\n      className=\"inline-flex rounded-full border border-rose bg-white p-0.5 text-sm font-semibold\">\n      {locales.map((l) => (\n        <Link key={l} href={`/${l}${path === '/' ? '' : path}`} lang={l} hrefLang={l}\n          aria-current={l === locale ? 'true' : undefined}\n          className={`rounded-full px-3 py-1 ${l === locale ? 'bg-maroon text-white' : 'text-charcoal hover:bg-rose'}`}>\n          {LANG_LABEL[l]}\n        </Link>\n      ))}\n    </div>\n  );\n\n  return (\n    <header className=\"sticky top-0 z-50 border-b border-rose bg-white\">\n      <div className=\"mx-auto flex h-16 max-w-7xl items-center justify-between gap-4 px-4 lg:px-8\">\n        {/* Brand: replace with the ashram logo image when supplied */}\n        <Link href={href('')} className=\"flex min-w-0 shrink items-center gap-2 leading-tight sm:gap-3\">\n          <span aria-hidden=\"true\" className=\"flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-maroon text-saffron sm:h-10 sm:w-10\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M12 2c.6 3.2 4.5 5.4 4.5 10a4.5 4.5 0 0 1-9 0c0-2 .9-3.2 1.8-4.4.4 1.2 1 1.8 1.7 2C11.3 7.7 11.6 5 12 2z\" /></svg>\n          </span>\n          <span className=\"flex flex-col\">\n            <span className=\"brand-name font-serif text-[1.4rem] font-bold sm:text-[1.75rem] leading-none text-maroon\">{siteName}</span>\n            <span className=\"hidden truncate text-xs text-charcoal/70 2xl:block\">{tagline}</span>\n          </span>\n        </Link>\n\n        {/* Desktop menu */}\n        <nav aria-label={a11y.mainNavigation} className=\"hidden min-w-0 xl:block\">\n          <ul className=\"flex items-center gap-1\">\n            {NAV.map((item) =>\n              'children' in item ? (\n                <li key={item.key} ref={dropdownRef} className=\"relative\"\n                  onMouseEnter={() => setDropdown(true)} onMouseLeave={() => setDropdown(false)}>\n                  <button type=\"button\" aria-haspopup=\"true\" aria-expanded={dropdown}\n                    onClick={() => setDropdown((o) => !o)}\n                    className={`${linkClass(item.children.some((c) => isActive(c.href)))} inline-flex items-center gap-1`}>\n                    {labels[item.key]}\n                    <Chevron open={dropdown} />\n                  </button>\n                  {dropdown && (\n                    <ul className=\"absolute left-0 top-full z-50 w-48 rounded-lg border border-rose bg-white py-1 shadow-lg\">\n                      {item.children.map((c) => (\n                        <li key={c.key}>\n                          <Link href={href(c.href)} aria-current={isActive(c.href) ? 'page' : undefined}\n                            className={`block px-4 py-2 text-[15px] hover:bg-rose hover:text-maroon ${isActive(c.href) ? 'font-semibold text-maroon' : 'text-charcoal'}`}>\n                            {labels[c.key]}\n                          </Link>\n                        </li>\n                      ))}\n                    </ul>\n                  )}\n                </li>\n              ) : (\n                <li key={item.key}>\n                  <Link href={href(item.href)} aria-current={isActive(item.href) ? 'page' : undefined}\n                    className={linkClass(isActive(item.href))}>\n                    {labels[item.key]}\n                  </Link>\n                </li>\n              ),\n            )}\n          </ul>\n        </nav>\n\n        {/* Right side: language switch, login, hamburger */}\n        <div className=\"flex shrink-0 items-center gap-1 sm:gap-3\">\n          {languageSwitch}\n          <CartLink href={href('/cart')} label={cartLabel} />\n          <Link href={href('/login')}\n            className=\"hidden rounded-md border-2 border-maroon px-4 py-1.5 text-[15px] font-semibold text-maroon transition-colors hover:bg-maroon hover:text-white xl:inline-flex\">\n            {labels.login}\n          </Link>\n          <button type=\"button\" className=\"rounded-md p-1.5 text-maroon sm:p-2 xl:hidden\"\n            aria-label={mobileOpen ? a11y.closeMenu : a11y.openMenu}\n            aria-expanded={mobileOpen} aria-controls=\"mobile-menu\"\n            onClick={() => setMobileOpen((o) => !o)}>\n            <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\"\n              strokeLinecap=\"round\" aria-hidden=\"true\">\n              {mobileOpen ? <path d=\"M6 6l12 12M18 6L6 18\" /> : <path d=\"M4 7h16M4 12h16M4 17h16\" />}\n            </svg>\n          </button>\n        </div>\n      </div>\n\n      {/* Mobile menu */}\n      <nav id=\"mobile-menu\" aria-label={a11y.mainNavigation}\n        className={`border-t border-rose bg-white xl:hidden ${mobileOpen ? '' : 'hidden'}`}>\n        <ul className=\"mx-auto max-w-7xl px-4 py-2\">\n          {NAV.map((item) =>\n            'children' in item ? (\n              <li key={item.key}>\n                <button type=\"button\" aria-expanded={mobileSub} onClick={() => setMobileSub((o) => !o)}\n                  className=\"flex w-full items-center justify-between rounded-md px-3 py-3 text-left font-medium text-charcoal hover:bg-rose\">\n                  {labels[item.key]}\n                  <Chevron open={mobileSub} />\n                </button>\n                {mobileSub && (\n                  <ul className=\"mb-1 ml-3 border-l-2 border-saffron\">\n                    {item.children.map((c) => (\n                      <li key={c.key}>\n                        <Link href={href(c.href)}\n                          className={`block px-4 py-2.5 hover:bg-rose ${isActive(c.href) ? 'font-semibold text-maroon' : 'text-charcoal'}`}>\n                          {labels[c.key]}\n                        </Link>\n                      </li>\n                    ))}\n                  </ul>\n                )}\n              </li>\n            ) : (\n              <li key={item.key}>\n                <Link href={href(item.href)} aria-current={isActive(item.href) ? 'page' : undefined}\n                  className={`block rounded-md px-3 py-3 font-medium hover:bg-rose ${isActive(item.href) ? 'bg-rose text-maroon' : 'text-charcoal'}`}>\n                  {labels[item.key]}\n                </Link>\n              </li>\n            ),\n          )}\n          <li className=\"px-3 pb-3 pt-2\">\n            <Link href={href('/login')}\n              className=\"block rounded-md border-2 border-maroon py-2.5 text-center font-semibold text-maroon hover:bg-maroon hover:text-white\">\n              {labels.login}\n            </Link>\n          </li>\n        </ul>\n      </nav>\n    </header>\n  );\n}\n","src/app/[locale]/layout.tsx":"import type { ReactNode } from 'react';\nimport { notFound } from 'next/navigation';\nimport { isLocale, locales } from '@/lib/i18n';\nimport { getDictionary } from '@/lib/dictionary';\nimport Footer from '@/components/Footer';\nimport Header from '@/components/Header';\nimport CartProvider from '@/components/cart/CartProvider';\nimport '@fontsource/cormorant-garamond/600.css';\nimport '@fontsource/cormorant-garamond/700.css';\nimport '@fontsource/lora/600.css';\nimport '@fontsource/lora/700.css';\nimport '@fontsource/noto-serif-tamil/600.css';\nimport '@fontsource/noto-serif-tamil/700.css';\nimport '@fontsource/mukta-malar/400.css';\nimport '@fontsource/mukta-malar/500.css';\nimport '@fontsource/mukta-malar/600.css';\nimport '@fontsource/mukta-malar/700.css';\nimport '../globals.css';\n\nexport const generateStaticParams = () => locales.map((locale) => ({ locale }));\n\nexport default async function RootLayout({\n  children,\n  params,\n}: {\n  children: ReactNode;\n  params: Promise<{ locale: string }>;\n}) {\n  const { locale } = await params;\n  if (!isLocale(locale)) notFound();\n  const t = getDictionary(locale);\n  return (\n    <html lang={locale}>\n      <body>\n        <CartProvider>\n          <Header locale={locale} siteName={t.site.name} tagline={t.site.tagline} labels={t.nav} a11y={t.a11y} cartLabel={t.shop.cartLabel} />\n          {children}\n          <Footer locale={locale} t={t.footer} />\n        </CartProvider>\n      </body>\n    </html>\n  );\n}\n","src/app/[locale]/sevas/[slug]/page.tsx":"import type { Metadata } from 'next';\nimport Link from 'next/link';\nimport { notFound } from 'next/navigation';\nimport SevaCard from '@/components/sevas/SevaCard';\nimport SevaPurchase from '@/components/sevas/SevaPurchase';\nimport SectionTitle from '@/components/SectionTitle';\nimport { SEVAS, getSeva, txt } from '@/data/sevas';\nimport { getDictionary } from '@/lib/dictionary';\nimport { rupees, sevaPhoto } from '@/lib/format';\nimport { isLocale, locales } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string; slug: string }> };\n\nexport const dynamicParams = false;\nexport const generateStaticParams = () => locales.flatMap((locale) => SEVAS.map((s) => ({ locale, slug: s.slug })));\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale, slug } = await params;\n  const seva = getSeva(slug);\n  if (!isLocale(locale) || !seva) return {};\n  const t = getDictionary(locale);\n  return { title: `${txt(seva.name, locale)} | ${t.site.name}` };\n}\n\nfunction Calendar() {\n  return (\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\" className=\"shrink-0\">\n      <rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2\" />\n      <path d=\"M3 10h18M8 3v4M16 3v4\" />\n    </svg>\n  );\n}\n\nexport default async function SevaDetailPage({ params }: Params) {\n  const { locale, slug } = await params;\n  if (!isLocale(locale)) notFound();\n  const seva = getSeva(slug);\n  if (!seva) notFound();\n\n  const dict = getDictionary(locale);\n  const t = dict.sevas;\n  const name = txt(seva.name, locale);\n  const kindLabel = t.filters.find((f) => f.key === seva.kind)?.label ?? '';\n  const paragraphs = seva.description[locale];\n  const related = SEVAS.filter((s) => s.kind === seva.kind && s.slug !== seva.slug).slice(0, 3);\n  const href = (p: string) => `/${locale}${p}`;\n\n  return (\n    <main>\n      <section className=\"bg-gradient-to-b from-rose/80 to-white\">\n        <nav aria-label={t.crumbLabel} className=\"mx-auto max-w-6xl px-4 pb-2 pt-6 text-sm text-charcoal/80 lg:px-8\">\n          <ol className=\"flex flex-wrap items-center gap-2\">\n            <li><Link href={href('')} className=\"underline-offset-4 hover:text-maroon hover:underline\">{dict.nav.home}</Link></li>\n            <li aria-hidden=\"true\">/</li>\n            <li><Link href={href('/sevas')} className=\"underline-offset-4 hover:text-maroon hover:underline\">{dict.nav.seva}</Link></li>\n            <li aria-hidden=\"true\">/</li>\n            <li aria-current=\"page\" className=\"font-semibold text-maroon\">{name}</li>\n          </ol>\n        </nav>\n      </section>\n\n      {/* Photo on the left, details and booking form on the right */}\n      <section className=\"bg-white pb-12 pt-4 sm:pb-16\">\n        <div className=\"mx-auto grid max-w-6xl items-start gap-10 px-4 lg:grid-cols-2 lg:gap-14 lg:px-8\">\n          <div className=\"lg:sticky lg:top-24\">\n            <div className=\"relative pb-4 pr-4\">\n              <div aria-hidden=\"true\" className=\"absolute inset-0 translate-x-4 translate-y-4 rounded-2xl bg-maroon\" />\n              <div role=\"img\" aria-label={name} className=\"relative aspect-[4/3] w-full rounded-2xl bg-maroon bg-cover bg-center shadow-xl ring-4 ring-white\" style={{ backgroundImage: sevaPhoto(seva.slug) }} />\n            </div>\n          </div>\n\n          <div>\n            <p className=\"inline-block rounded-full bg-maroon px-4 py-1 text-xs font-bold uppercase tracking-wider text-white [html[lang='ta']_&]:tracking-normal\">{kindLabel}</p>\n            <h1 className=\"mt-3 font-display text-4xl font-semibold leading-tight text-maroon sm:text-5xl [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-3xl [html[lang='ta']_&]:sm:text-4xl\">{name}</h1>\n\n            <dl className=\"mt-5 grid gap-4 rounded-xl bg-rose/50 p-5 sm:grid-cols-2\">\n              <div>\n                <dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.amountLabel}</dt>\n                <dd className=\"mt-1 font-display text-3xl font-semibold text-charcoal\">\n                  {seva.amount > 0 ? rupees(seva.amount) : <span className=\"text-2xl text-saffron [html[lang='ta']_&]:text-xl\">{t.abilityLabel}</span>}\n                </dd>\n              </div>\n              <div>\n                <dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.whenLabel}</dt>\n                <dd className=\"mt-1 flex items-center gap-2 text-lg font-semibold text-charcoal\"><Calendar />{txt(seva.when, locale)}</dd>\n              </div>\n            </dl>\n\n            <div className=\"mt-6\">\n              <SevaPurchase seva={seva} locale={locale} t={t} />\n            </div>\n          </div>\n        </div>\n      </section>\n\n      {/* About */}\n      <section aria-labelledby=\"about-title\" className=\"bg-rose/50 py-12 sm:py-16\">\n        <div className=\"mx-auto max-w-4xl px-4 lg:px-8\">\n          <h2 id=\"about-title\" className=\"font-display text-3xl font-semibold text-maroon sm:text-4xl [html[lang='ta']_&]:!leading-[1.3]\">{t.aboutTitle}</h2>\n          <div aria-hidden=\"true\" className=\"mt-3 flex items-center gap-3\"><span className=\"h-px w-12 bg-saffron\" /><span className=\"h-2 w-2 rotate-45 bg-saffron\" /><span className=\"h-px w-12 bg-saffron\" /></div>\n          {paragraphs.length > 0 ? (\n            paragraphs.map((p) => <p key={p} className=\"mt-5 font-serif text-lg leading-relaxed text-charcoal\">{p}</p>)\n          ) : (\n            <p className=\"mt-5 font-serif text-lg leading-relaxed text-charcoal/80\">{t.descriptionEmpty}</p>\n          )}\n\n          {seva.includes.length > 0 && (\n            <div className=\"mt-10\">\n              <h3 className=\"font-display text-2xl font-semibold text-maroon\">{t.includesTitle}</h3>\n              <ul className=\"mt-4 divide-y divide-rose overflow-hidden rounded-xl bg-white ring-1 ring-rose\">\n                {seva.includes.map((i) => (\n                  <li key={i.label.en} className=\"flex items-start justify-between gap-4 px-5 py-3\">\n                    <span className=\"text-charcoal\">{txt(i.label, locale)}</span>\n                    <span className=\"shrink-0 font-bold text-charcoal\">{rupees(i.price)}</span>\n                  </li>\n                ))}\n              </ul>\n            </div>\n          )}\n        </div>\n      </section>\n\n      {/* How to book */}\n      <section aria-labelledby=\"how-title\" className=\"bg-white py-12 sm:py-16\">\n        <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n          <SectionTitle id=\"how-title\" title={t.howTitle} />\n          <ol className=\"mt-10 grid gap-6 sm:grid-cols-2 lg:grid-cols-4\">\n            {t.howSteps.map((s, i) => (\n              <li key={s.title} className=\"rounded-2xl border-t-4 border-saffron bg-rose/40 p-6 text-center\">\n                <span aria-hidden=\"true\" className=\"mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-maroon font-display text-2xl font-semibold text-white\">{i + 1}</span>\n                <h3 className=\"mt-3 font-display text-xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.4]\">{s.title}</h3>\n                <p className=\"mt-1 text-charcoal/85\">{s.text}</p>\n              </li>\n            ))}\n          </ol>\n        </div>\n      </section>\n\n      {/* Related sevas */}\n      {related.length > 0 && (\n        <section aria-labelledby=\"related-title\" className=\"bg-rose/50 py-12 sm:py-16\">\n          <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n            <SectionTitle id=\"related-title\" title={t.relatedTitle} />\n            <ul className=\"mt-10 grid gap-6 sm:grid-cols-2 lg:grid-cols-3\">\n              {related.map((s) => (\n                <li key={s.slug} className=\"h-full\"><SevaCard seva={s} locale={locale} t={t} /></li>\n              ))}\n            </ul>\n            <p className=\"mt-8 text-center\">\n              <Link href={href('/sevas')} className=\"font-bold text-maroon underline underline-offset-4\">{t.backLabel}</Link>\n            </p>\n          </div>\n        </section>\n      )}\n    </main>\n  );\n}\n","src/app/[locale]/cart/page.tsx":"import type { Metadata } from 'next';\nimport { notFound } from 'next/navigation';\nimport CartView from '@/components/cart/CartView';\nimport ShopHero from '@/components/cart/ShopHero';\nimport { getDictionary } from '@/lib/dictionary';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return { title: `${t.shop.cartTitle} | ${t.site.name}`, robots: { index: false } };\n}\n\nexport default async function Page({ params }: Params) {\n  const { locale } = await params;\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.shop;\n  return (\n    <main>\n      <ShopHero\n        title={t.cartTitle}\n        crumbLabel={t.crumbLabel}\n        crumbs={[{ label: dict.nav.home, href: `/${locale}` }, { label: dict.nav.seva, href: `/${locale}/sevas` }, { label: t.cartTitle }]}\n        steps={t.steps}\n        current={0}\n      />\n      <section className=\"bg-white pb-16 pt-4 sm:pb-20\">\n        <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n          <CartView t={t} locale={locale} />\n        </div>\n      </section>\n    </main>\n  );\n}\n","src/app/[locale]/checkout/page.tsx":"import type { Metadata } from 'next';\nimport { notFound } from 'next/navigation';\nimport CheckoutForm from '@/components/cart/CheckoutForm';\nimport ShopHero from '@/components/cart/ShopHero';\nimport { getDictionary } from '@/lib/dictionary';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return { title: `${t.shop.checkoutTitle} | ${t.site.name}`, robots: { index: false } };\n}\n\nexport default async function Page({ params }: Params) {\n  const { locale } = await params;\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.shop;\n  return (\n    <main>\n      <ShopHero\n        title={t.checkoutTitle}\n        crumbLabel={t.crumbLabel}\n        crumbs={[{ label: dict.nav.home, href: `/${locale}` }, { label: dict.nav.seva, href: `/${locale}/sevas` }, { label: t.checkoutTitle }]}\n        steps={t.steps}\n        current={1}\n      />\n      <section className=\"bg-white pb-16 pt-4 sm:pb-20\">\n        <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n          <CheckoutForm t={t} locale={locale} />\n        </div>\n      </section>\n    </main>\n  );\n}\n","src/app/[locale]/payment/page.tsx":"import type { Metadata } from 'next';\nimport { notFound } from 'next/navigation';\nimport PaymentView from '@/components/cart/PaymentView';\nimport ShopHero from '@/components/cart/ShopHero';\nimport { getDictionary } from '@/lib/dictionary';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return { title: `${t.shop.paymentTitle} | ${t.site.name}`, robots: { index: false } };\n}\n\nexport default async function Page({ params }: Params) {\n  const { locale } = await params;\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.shop;\n  return (\n    <main>\n      <ShopHero\n        title={t.paymentTitle}\n        crumbLabel={t.crumbLabel}\n        crumbs={[{ label: dict.nav.home, href: `/${locale}` }, { label: dict.nav.seva, href: `/${locale}/sevas` }, { label: t.paymentTitle }]}\n        steps={t.steps}\n        current={2}\n      />\n      <section className=\"bg-white pb-16 pt-4 sm:pb-20\">\n        <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n          <PaymentView t={t} locale={locale} />\n        </div>\n      </section>\n    </main>\n  );\n}\n","src/app/[locale]/order-confirmation/page.tsx":"import type { Metadata } from 'next';\nimport { notFound } from 'next/navigation';\nimport ConfirmationView from '@/components/cart/ConfirmationView';\nimport ShopHero from '@/components/cart/ShopHero';\nimport { getDictionary } from '@/lib/dictionary';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return { title: `${t.shop.confirmPageTitle} | ${t.site.name}`, robots: { index: false } };\n}\n\nexport default async function Page({ params }: Params) {\n  const { locale } = await params;\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.shop;\n  return (\n    <main>\n      <ShopHero\n        title={t.confirmPageTitle}\n        crumbLabel={t.crumbLabel}\n        crumbs={[{ label: dict.nav.home, href: `/${locale}` }, { label: dict.nav.seva, href: `/${locale}/sevas` }, { label: t.confirmPageTitle }]}\n        steps={t.steps}\n        current={3}\n      />\n      <section className=\"bg-white pb-16 pt-4 sm:pb-20\">\n        <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n          <ConfirmationView t={t} locale={locale} />\n        </div>\n      </section>\n    </main>\n  );\n}\n","src/components/cart/CartLink.tsx":"'use client';\n\nimport Link from 'next/link';\nimport { useCart } from './CartProvider';\n\n// Shopping-bag icon with the number of selected sevas, for the header\nexport default function CartLink({ href, label }: { href: string; label: string }) {\n  const { count, ready } = useCart();\n  const n = ready ? count : 0;\n  return (\n    <Link\n      href={href}\n      aria-label={n > 0 ? `${label}: ${n}` : label}\n      className=\"relative inline-flex h-9 w-9 items-center sm:h-10 sm:w-10 justify-center rounded-full text-maroon transition-colors hover:bg-rose focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\"\n    >\n      <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\">\n        <path d=\"M6 7h12l1 13H5L6 7z\" />\n        <path d=\"M9 7a3 3 0 0 1 6 0\" />\n      </svg>\n      {n > 0 && (\n        <span aria-hidden=\"true\" className=\"absolute -right-0.5 -top-0.5 flex h-5 min-w-[1.25rem] items-center justify-center rounded-full bg-saffron px-1 text-xs font-bold text-charcoal\">\n          {n}\n        </span>\n      )}\n    </Link>\n  );\n}\n","src/components/cart/CartProvider.tsx":"'use client';\n\n// The cart lives in the browser (localStorage) while the site is UI-only.\n// When the backend is ready, replace the read/write calls below with API calls.\n\nimport { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';\n\nexport type CartLine = {\n  id: string;\n  slug: string;\n  qty: number;\n  unit: number;       // amount for one, in rupees\n  date: string;       // YYYY-MM-DD\n  devotee: string;\n  gotram: string;\n  nakshatram: string;\n};\n\nexport type Contact = { name: string; phone: string; email: string; address: string; city: string; state: string; pin: string; country: string };\nexport const EMPTY_CONTACT: Contact = { name: '', phone: '', email: '', address: '', city: '', state: '', pin: '', country: 'India' };\n\nexport type Order = { id: string; placedAt: string; lines: CartLine[]; total: number; contact: Contact; method: string };\n\nconst KEY_CART = 'vedaneri.cart.v1';\nconst KEY_CONTACT = 'vedaneri.contact.v1';\nconst KEY_ORDER = 'vedaneri.order.v1';\n\n// Browser storage can be blocked or empty (private windows), so every call is wrapped.\nfunction read<T>(key: string, fallback: T): T {\n  try {\n    const raw = window.localStorage.getItem(key);\n    return raw ? (JSON.parse(raw) as T) : fallback;\n  } catch {\n    return fallback;\n  }\n}\nfunction write(key: string, value: unknown) {\n  try {\n    window.localStorage.setItem(key, JSON.stringify(value));\n  } catch {\n    /* ignore */\n  }\n}\n\ntype CartContextValue = {\n  ready: boolean;                 // false until the saved cart has been read\n  lines: CartLine[];\n  count: number;                  // number of sevas (quantities added up)\n  total: number;\n  add: (line: Omit<CartLine, 'id'>) => void;\n  setQty: (id: string, qty: number) => void;\n  remove: (id: string) => void;\n  contact: Contact;\n  saveContact: (c: Contact) => void;\n  order: Order | null;            // the last paid order\n  placeOrder: (method: string) => Order | null;\n};\n\nconst CartContext = createContext<CartContextValue | null>(null);\n\nexport function useCart() {\n  const ctx = useContext(CartContext);\n  if (!ctx) throw new Error('useCart must be used inside <CartProvider>');\n  return ctx;\n}\n\nexport default function CartProvider({ children }: { children: ReactNode }) {\n  const [ready, setReady] = useState(false);\n  const [lines, setLines] = useState<CartLine[]>([]);\n  const [contact, setContact] = useState<Contact>(EMPTY_CONTACT);\n  const [order, setOrder] = useState<Order | null>(null);\n\n  useEffect(() => {\n    setLines(read<CartLine[]>(KEY_CART, []));\n    setContact({ ...EMPTY_CONTACT, ...read<Partial<Contact>>(KEY_CONTACT, {}) });\n    setOrder(read<Order | null>(KEY_ORDER, null));\n    setReady(true);\n  }, []);\n\n  useEffect(() => {\n    if (!ready) return;\n    write(KEY_CART, lines);\n    write(KEY_CONTACT, contact);\n    write(KEY_ORDER, order);\n  }, [ready, lines, contact, order]);\n\n  const add = useCallback((line: Omit<CartLine, 'id'>) => {\n    const id = `${line.slug}-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;\n    setLines((l) => [...l, { ...line, id }]);\n  }, []);\n\n  const setQty = useCallback((id: string, qty: number) => {\n    setLines((l) => l.map((x) => (x.id === id ? { ...x, qty } : x)));\n  }, []);\n\n  const remove = useCallback((id: string) => setLines((l) => l.filter((x) => x.id !== id)), []);\n\n  const saveContact = useCallback((c: Contact) => setContact(c), []);\n\n  const total = useMemo(() => lines.reduce((s, l) => s + l.unit * l.qty, 0), [lines]);\n  const count = useMemo(() => lines.reduce((s, l) => s + l.qty, 0), [lines]);\n\n  const placeOrder = useCallback(\n    (method: string) => {\n      if (lines.length === 0) return null;\n      const d = new Date();\n      const stamp = `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;\n      const o: Order = {\n        id: `VN-${stamp}-${Math.floor(1000 + Math.random() * 9000)}`,\n        placedAt: d.toISOString(),\n        lines,\n        total,\n        contact,\n        method,\n      };\n      setOrder(o);\n      setLines([]);\n      return o;\n    },\n    [lines, total, contact],\n  );\n\n  const value = useMemo<CartContextValue>(\n    () => ({ ready, lines, count, total, add, setQty, remove, contact, saveContact, order, placeOrder }),\n    [ready, lines, count, total, add, setQty, remove, contact, saveContact, order, placeOrder],\n  );\n\n  return <CartContext.Provider value={value}>{children}</CartContext.Provider>;\n}\n","src/components/cart/CartView.tsx":"'use client';\n\nimport Link from 'next/link';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { formatDate, rupees, sevaPhoto } from '@/lib/format';\nimport { getSeva, txt } from '@/data/sevas';\nimport { useCart } from './CartProvider';\n\nexport default function CartView({ t, locale }: { t: Dictionary['shop']; locale: Locale }) {\n  const { ready, lines, count, total, setQty, remove } = useCart();\n  const href = (p: string) => `/${locale}${p}`;\n\n  if (!ready) return <p role=\"status\" className=\"py-16 text-center text-charcoal/70\">{t.loading}</p>;\n\n  if (lines.length === 0) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-display text-3xl font-semibold text-maroon\">{t.cartEmpty}</p>\n        <p className=\"mt-2 font-serif text-lg text-charcoal/90\">{t.cartEmptyText}</p>\n        <Link href={href('/sevas')} className=\"mt-6 inline-block rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.browse}</Link>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"grid items-start gap-8 lg:grid-cols-[1fr_360px]\">\n      <ul className=\"space-y-4\">\n        {lines.map((l) => {\n          const seva = getSeva(l.slug);\n          const name = seva ? txt(seva.name, locale) : l.slug;\n          const fixedPrice = seva ? seva.amount > 0 : false;\n          const max = seva?.maxQty ?? 10;\n          return (\n            <li key={l.id} className=\"flex flex-col gap-4 rounded-2xl bg-white p-4 shadow-md ring-1 ring-rose sm:flex-row sm:p-5\">\n              <div role=\"img\" aria-label={name} className=\"h-32 w-full shrink-0 rounded-xl bg-maroon bg-cover bg-center sm:h-28 sm:w-36\" style={{ backgroundImage: sevaPhoto(l.slug) }} />\n              <div className=\"flex min-w-0 flex-1 flex-col\">\n                <h2 className=\"font-display text-2xl font-semibold leading-tight text-maroon [html[lang='ta']_&]:!leading-[1.4] [html[lang='ta']_&]:text-xl\">\n                  <Link href={href(`/sevas/${l.slug}`)} className=\"hover:underline\">{name}</Link>\n                </h2>\n                <dl className=\"mt-2 grid gap-x-6 gap-y-1 text-sm sm:grid-cols-2\">\n                  <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.dateLabel}:</dt><dd>{formatDate(l.date, locale)}</dd></div>\n                  <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.devoteeLabel}:</dt><dd>{l.devotee}</dd></div>\n                  {l.gotram && <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.gotramLabel}:</dt><dd>{l.gotram}</dd></div>}\n                  {l.nakshatram && <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.nakshatramLabel}:</dt><dd>{l.nakshatram}</dd></div>}\n                </dl>\n\n                <div className=\"mt-4 flex flex-wrap items-center justify-between gap-3\">\n                  {fixedPrice ? (\n                    <div className=\"inline-flex items-center rounded-md border-2 border-rose\" role=\"group\" aria-label={t.qtyLabel}>\n                      <button type=\"button\" aria-label={t.decrease} disabled={l.qty <= 1} onClick={() => setQty(l.id, l.qty - 1)} className=\"h-10 w-10 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">−</button>\n                      <span aria-live=\"polite\" className=\"w-10 text-center font-bold\">{l.qty}</span>\n                      <button type=\"button\" aria-label={t.increase} disabled={l.qty >= max} onClick={() => setQty(l.id, l.qty + 1)} className=\"h-10 w-10 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">+</button>\n                    </div>\n                  ) : (\n                    <span className=\"text-sm text-charcoal/70\">{t.yourAmount}</span>\n                  )}\n                  <p className=\"font-display text-3xl font-semibold text-charcoal\">{rupees(l.qty * l.unit)}</p>\n                </div>\n                <button type=\"button\" onClick={() => remove(l.id)} className=\"mt-3 self-start text-sm font-semibold text-maroon underline underline-offset-4 hover:text-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-saffron\">{t.remove}</button>\n              </div>\n            </li>\n          );\n        })}\n      </ul>\n\n      <aside aria-label={t.summaryTitle} className=\"rounded-2xl bg-white p-6 shadow-lg ring-2 ring-rose lg:sticky lg:top-24\">\n        <h2 className=\"font-display text-2xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.4]\">{t.summaryTitle}</h2>\n        <dl className=\"mt-4 space-y-2\">\n          <div className=\"flex justify-between\"><dt className=\"text-charcoal/80\">{t.itemsLabel}</dt><dd className=\"font-semibold\">{count}</dd></div>\n          <div className=\"flex items-baseline justify-between border-t-2 border-rose pt-4\">\n            <dt className=\"font-bold\">{t.total}</dt>\n            <dd className=\"font-display text-3xl font-semibold text-maroon\">{rupees(total)}</dd>\n          </div>\n        </dl>\n        <Link href={href('/checkout')} className=\"mt-6 block rounded-md bg-maroon px-5 py-3 text-center font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.checkoutCta}</Link>\n        <Link href={href('/sevas')} className=\"mt-3 block text-center text-sm font-semibold text-maroon underline underline-offset-4\">{t.continueShopping}</Link>\n        <p className=\"mt-4 text-center text-xs text-charcoal/70\">{t.receiptNote}</p>\n      </aside>\n    </div>\n  );\n}\n","src/components/cart/CheckoutForm.tsx":"'use client';\n\nimport { useState } from 'react';\nimport Link from 'next/link';\nimport { useRouter } from 'next/navigation';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { useCart, type Contact } from './CartProvider';\nimport OrderSummary from './OrderSummary';\n\nconst inputClass =\n  'w-full rounded-md border-2 border-rose bg-white px-4 py-2.5 text-charcoal placeholder:text-charcoal/50 focus:border-saffron focus:outline-none';\n\nfunction Field({ id, label, error, className = '', children }: { id: string; label: string; error?: string; className?: string; children: React.ReactNode }) {\n  return (\n    <div className={className}>\n      <label htmlFor={id} className=\"block text-sm font-bold text-charcoal\">{label}</label>\n      <div className=\"mt-1\">{children}</div>\n      {error && <p id={`${id}-error`} role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{error}</p>}\n    </div>\n  );\n}\n\nexport default function CheckoutForm({ t, locale }: { t: Dictionary['shop']; locale: Locale }) {\n  const router = useRouter();\n  const { ready, lines, total, contact, saveContact } = useCart();\n  const [form, setForm] = useState<Contact | null>(null);\n  const [errors, setErrors] = useState<Partial<Record<keyof Contact, string>>>({});\n  const href = (p: string) => `/${locale}${p}`;\n\n  if (!ready) return <p role=\"status\" className=\"py-16 text-center text-charcoal/70\">{t.loading}</p>;\n\n  if (lines.length === 0) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-display text-3xl font-semibold text-maroon\">{t.cartEmpty}</p>\n        <Link href={href('/sevas')} className=\"mt-6 inline-block rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal\">{t.browse}</Link>\n      </div>\n    );\n  }\n\n  // Start from what was saved the last time, then keep the visitor's edits\n  const v = form ?? contact;\n  const set = (k: keyof Contact) => (e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...v, [k]: e.target.value });\n\n  function submit(e: React.FormEvent) {\n    e.preventDefault();\n    const er: Partial<Record<keyof Contact, string>> = {};\n    if (!v.name.trim()) er.name = t.errName;\n    if (!/^\\+?[\\d\\s-]{7,15}$/.test(v.phone.trim())) er.phone = t.errPhone;\n    if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(v.email.trim())) er.email = t.errEmail;\n    if (!v.address.trim()) er.address = t.errAddress;\n    if (!v.city.trim()) er.city = t.errCity;\n    if (!v.state.trim()) er.state = t.errState;\n    if (!v.pin.trim()) er.pin = t.errPin;\n    if (!v.country.trim()) er.country = t.errCountry;\n    setErrors(er);\n    if (Object.keys(er).length) return;\n    saveContact({ ...v, name: v.name.trim(), phone: v.phone.trim(), email: v.email.trim() });\n    router.push(href('/payment'));\n  }\n\n  const f = (k: keyof Contact) => ({ id: k, value: v[k], onChange: set(k), 'aria-invalid': !!errors[k], 'aria-describedby': errors[k] ? `${k}-error` : undefined, className: inputClass });\n\n  return (\n    <div className=\"grid items-start gap-8 lg:grid-cols-[1fr_360px]\">\n      <form noValidate onSubmit={submit} className=\"rounded-2xl bg-white p-6 shadow-lg ring-2 ring-rose sm:p-8\">\n        <h2 className=\"font-display text-2xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.4]\">{t.contactTitle}</h2>\n        <p className=\"mt-1 text-sm text-charcoal/70\">{t.contactHelp}</p>\n\n        <div className=\"mt-6 grid gap-4 sm:grid-cols-2\">\n          <Field id=\"name\" label={t.fName} error={errors.name} className=\"sm:col-span-2\"><input {...f('name')} autoComplete=\"name\" /></Field>\n          <Field id=\"phone\" label={t.fPhone} error={errors.phone}><input {...f('phone')} type=\"tel\" autoComplete=\"tel\" inputMode=\"tel\" /></Field>\n          <Field id=\"email\" label={t.fEmail} error={errors.email}><input {...f('email')} type=\"email\" autoComplete=\"email\" /></Field>\n          <Field id=\"address\" label={t.fAddress} error={errors.address} className=\"sm:col-span-2\"><input {...f('address')} autoComplete=\"street-address\" /></Field>\n          <Field id=\"city\" label={t.fCity} error={errors.city}><input {...f('city')} autoComplete=\"address-level2\" /></Field>\n          <Field id=\"state\" label={t.fState} error={errors.state}><input {...f('state')} autoComplete=\"address-level1\" /></Field>\n          <Field id=\"pin\" label={t.fPin} error={errors.pin}><input {...f('pin')} autoComplete=\"postal-code\" /></Field>\n          <Field id=\"country\" label={t.fCountry} error={errors.country}><input {...f('country')} autoComplete=\"country-name\" /></Field>\n        </div>\n\n        <div className=\"mt-8 flex flex-col-reverse gap-3 sm:flex-row sm:justify-between\">\n          <Link href={href('/cart')} className=\"rounded-md border-2 border-maroon px-6 py-3 text-center font-semibold text-maroon hover:bg-rose\">{t.backToCart}</Link>\n          <button type=\"submit\" className=\"rounded-md bg-maroon px-8 py-3 font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.continuePayment}</button>\n        </div>\n      </form>\n\n      <div className=\"lg:sticky lg:top-24\">\n        <OrderSummary lines={lines} total={total} locale={locale} t={t} />\n      </div>\n    </div>\n  );\n}\n","src/components/cart/ConfirmationView.tsx":"'use client';\n\nimport Link from 'next/link';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { formatDate, rupees } from '@/lib/format';\nimport { getSeva, txt } from '@/data/sevas';\nimport { useCart } from './CartProvider';\n\nexport default function ConfirmationView({ t, locale }: { t: Dictionary['shop']; locale: Locale }) {\n  const { ready, order } = useCart();\n  const href = (p: string) => `/${locale}${p}`;\n\n  if (!ready) return <p role=\"status\" className=\"py-16 text-center text-charcoal/70\">{t.loading}</p>;\n\n  if (!order) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-serif text-lg text-charcoal\">{t.noOrder}</p>\n        <Link href={href('/sevas')} className=\"mt-6 inline-block rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal\">{t.browse}</Link>\n      </div>\n    );\n  }\n\n  const method = t.methods.find((m) => m.key === order.method)?.label ?? order.method;\n  const placed = order.placedAt.slice(0, 10);\n\n  return (\n    <div className=\"mx-auto max-w-3xl\">\n      <div className=\"rounded-2xl bg-white p-6 shadow-lg ring-2 ring-saffron sm:p-10\">\n        <div className=\"text-center\">\n          <span aria-hidden=\"true\" className=\"mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-saffron text-3xl font-bold text-charcoal\">✓</span>\n          <h2 className=\"mt-4 font-display text-4xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-3xl\">{t.confirmTitle}</h2>\n          <p className=\"mx-auto mt-2 max-w-xl font-serif text-lg text-charcoal/90\">{t.confirmText}</p>\n          <p className=\"mt-2 text-sm font-semibold text-charcoal/70\">{t.receiptSent.replace('{email}', order.contact.email)}</p>\n        </div>\n\n        <dl className=\"mt-8 grid gap-4 rounded-xl bg-rose/50 p-5 sm:grid-cols-3\">\n          <div><dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.orderId}</dt><dd className=\"mt-1 font-bold text-charcoal\">{order.id}</dd></div>\n          <div><dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.orderDate}</dt><dd className=\"mt-1 font-bold text-charcoal\">{formatDate(placed, locale)}</dd></div>\n          <div><dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.paidWith}</dt><dd className=\"mt-1 font-bold text-charcoal\">{method}</dd></div>\n        </dl>\n\n        <h3 className=\"mt-8 font-display text-2xl font-semibold text-maroon\">{t.yourSevas}</h3>\n        <ul className=\"mt-2 divide-y divide-rose\">\n          {order.lines.map((l) => {\n            const seva = getSeva(l.slug);\n            return (\n              <li key={l.id} className=\"flex items-start justify-between gap-4 py-3\">\n                <div>\n                  <p className=\"font-semibold text-charcoal\">{seva ? txt(seva.name, locale) : l.slug}</p>\n                  <p className=\"text-sm text-charcoal/70\">{formatDate(l.date, locale)} · {l.devotee}{l.gotram ? ` · ${l.gotram}` : ''}{l.nakshatram ? ` · ${l.nakshatram}` : ''}</p>\n                  <p className=\"text-sm text-charcoal/70\">{l.qty} × {rupees(l.unit)}</p>\n                </div>\n                <p className=\"shrink-0 font-bold\">{rupees(l.qty * l.unit)}</p>\n              </li>\n            );\n          })}\n        </ul>\n        <p className=\"mt-2 flex items-baseline justify-between border-t-2 border-rose pt-4\">\n          <span className=\"font-bold\">{t.total}</span>\n          <span className=\"font-display text-3xl font-semibold text-maroon\">{rupees(order.total)}</span>\n        </p>\n\n        <div className=\"mt-8 flex flex-col gap-3 sm:flex-row sm:justify-center\">\n          <Link href={href('/sevas')} className=\"rounded-md bg-maroon px-7 py-3 text-center font-semibold text-white hover:bg-charcoal\">{t.moreSevas}</Link>\n          <Link href={href('')} className=\"rounded-md border-2 border-maroon px-7 py-3 text-center font-semibold text-maroon hover:bg-rose\">{t.backHome}</Link>\n        </div>\n      </div>\n    </div>\n  );\n}\n","src/components/cart/OrderSummary.tsx":"import type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { formatDate, rupees, sevaPhoto } from '@/lib/format';\nimport { getSeva, txt } from '@/data/sevas';\nimport type { CartLine } from './CartProvider';\n\n// Compact list of the sevas in the order, with the total. Used beside checkout and payment.\nexport default function OrderSummary({ lines, total, locale, t }: { lines: CartLine[]; total: number; locale: Locale; t: Dictionary['shop'] }) {\n  return (\n    <aside aria-label={t.summaryTitle} className=\"rounded-2xl bg-white p-6 shadow-lg ring-2 ring-rose\">\n      <h2 className=\"font-display text-2xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.4]\">{t.summaryTitle}</h2>\n      <ul className=\"mt-4 divide-y divide-rose\">\n        {lines.map((l) => {\n          const seva = getSeva(l.slug);\n          return (\n            <li key={l.id} className=\"flex gap-3 py-3\">\n              <div role=\"img\" aria-label=\"\" className=\"h-14 w-14 shrink-0 rounded-lg bg-maroon bg-cover bg-center\" style={{ backgroundImage: sevaPhoto(l.slug) }} />\n              <div className=\"min-w-0 flex-1\">\n                <p className=\"font-semibold leading-snug text-charcoal\">{seva ? txt(seva.name, locale) : l.slug}</p>\n                <p className=\"text-sm text-charcoal/70\">{formatDate(l.date, locale)} · {l.devotee}</p>\n                <p className=\"text-sm text-charcoal/70\">{l.qty} × {rupees(l.unit)}</p>\n              </div>\n              <p className=\"shrink-0 font-bold text-charcoal\">{rupees(l.qty * l.unit)}</p>\n            </li>\n          );\n        })}\n      </ul>\n      <p className=\"mt-2 flex items-baseline justify-between border-t-2 border-rose pt-4\">\n        <span className=\"font-bold text-charcoal\">{t.total}</span>\n        <span className=\"font-display text-3xl font-semibold text-maroon\">{rupees(total)}</span>\n      </p>\n    </aside>\n  );\n}\n","src/components/cart/PaymentView.tsx":"'use client';\n\nimport { useState } from 'react';\nimport Link from 'next/link';\nimport { useRouter } from 'next/navigation';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { rupees } from '@/lib/format';\nimport { useCart } from './CartProvider';\nimport OrderSummary from './OrderSummary';\n\nexport default function PaymentView({ t, locale }: { t: Dictionary['shop']; locale: Locale }) {\n  const router = useRouter();\n  const { ready, lines, total, contact, placeOrder } = useCart();\n  const [method, setMethod] = useState('upi');\n  const [agree, setAgree] = useState(false);\n  const [error, setError] = useState('');\n  const [busy, setBusy] = useState(false);\n  const href = (p: string) => `/${locale}${p}`;\n\n  if (!ready) return <p role=\"status\" className=\"py-16 text-center text-charcoal/70\">{t.loading}</p>;\n\n  // After a successful payment the cart is emptied, so do not show the \"empty\" message while moving on\n  if (lines.length === 0 && !busy) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-display text-3xl font-semibold text-maroon\">{t.cartEmpty}</p>\n        <Link href={href('/sevas')} className=\"mt-6 inline-block rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal\">{t.browse}</Link>\n      </div>\n    );\n  }\n\n  if (!contact.name.trim() && !busy) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-serif text-lg text-charcoal\">{t.needDetails}</p>\n        <Link href={href('/checkout')} className=\"mt-6 inline-block rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal\">{t.backToDetails}</Link>\n      </div>\n    );\n  }\n\n  function pay() {\n    if (!agree) {\n      setError(t.errTerms);\n      return;\n    }\n    setError('');\n    setBusy(true);\n    // DEMO: no money moves. The real payment gateway is connected here later.\n    window.setTimeout(() => {\n      const order = placeOrder(method);\n      if (order) router.push(href('/order-confirmation'));\n      else setBusy(false);\n    }, 1800);\n  }\n\n  return (\n    <div className=\"grid items-start gap-8 lg:grid-cols-[1fr_360px]\">\n      <div className=\"rounded-2xl bg-white p-6 shadow-lg ring-2 ring-rose sm:p-8\">\n        <p className=\"rounded-md bg-saffron/15 px-4 py-2 text-sm font-semibold text-charcoal\">{t.demoNote}</p>\n\n        <fieldset className=\"mt-6\">\n          <legend className=\"font-display text-2xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.4]\">{t.methodTitle}</legend>\n          <div className=\"mt-4 space-y-3\">\n            {t.methods.map((m) => (\n              <label key={m.key} className={`flex cursor-pointer items-start gap-3 rounded-xl border-2 p-4 transition-colors ${method === m.key ? 'border-saffron bg-rose/50' : 'border-rose hover:bg-rose/30'}`}>\n                <input type=\"radio\" name=\"method\" value={m.key} checked={method === m.key} onChange={() => setMethod(m.key)} className=\"mt-1 h-4 w-4 accent-maroon\" />\n                <span>\n                  <span className=\"block font-bold text-charcoal\">{m.label}</span>\n                  <span className=\"block text-sm text-charcoal/70\">{m.hint}</span>\n                </span>\n              </label>\n            ))}\n          </div>\n        </fieldset>\n\n        <p className=\"mt-4 text-sm text-charcoal/70\">{t.redirectNote}</p>\n\n        <div className=\"mt-6\">\n          <label className=\"flex cursor-pointer items-start gap-3\">\n            <input type=\"checkbox\" checked={agree} onChange={(e) => { setAgree(e.target.checked); if (e.target.checked) setError(''); }} aria-describedby={error ? 'terms-error' : undefined} className=\"mt-1 h-4 w-4 accent-maroon\" />\n            <span className=\"text-charcoal\">{t.termsText}</span>\n          </label>\n          {error && <p id=\"terms-error\" role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{error}</p>}\n        </div>\n\n        <div className=\"mt-8 flex flex-col-reverse gap-3 sm:flex-row sm:justify-between\">\n          <Link href={href('/checkout')} className=\"rounded-md border-2 border-maroon px-6 py-3 text-center font-semibold text-maroon hover:bg-rose\">{t.backToDetails}</Link>\n          <button type=\"button\" onClick={pay} disabled={busy} className=\"rounded-md bg-maroon px-8 py-3 font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron disabled:cursor-wait disabled:opacity-70\">\n            {busy ? t.processing : t.payCta.replace('{amount}', rupees(total))}\n          </button>\n        </div>\n      </div>\n\n      <div className=\"lg:sticky lg:top-24\">\n        <OrderSummary lines={lines} total={total} locale={locale} t={t} />\n      </div>\n    </div>\n  );\n}\n","src/components/cart/ShopHero.tsx":"import Link from 'next/link';\n\ntype Crumb = { label: string; href?: string };\n\n// Title band for the cart, checkout, payment and confirmation pages, with the 4-step progress bar\nexport default function ShopHero({\n  title,\n  crumbs,\n  crumbLabel,\n  steps,\n  current,\n}: {\n  title: string;\n  crumbs: Crumb[];\n  crumbLabel: string;\n  steps?: string[];\n  current?: number; // 0-based index of the step the visitor is on\n}) {\n  return (\n    <section className=\"bg-gradient-to-b from-rose/80 to-white\">\n      <div className=\"mx-auto max-w-6xl px-4 pb-8 pt-6 lg:px-8\">\n        <nav aria-label={crumbLabel} className=\"text-sm text-charcoal/80\">\n          <ol className=\"flex flex-wrap items-center gap-2\">\n            {crumbs.map((c, i) => (\n              <li key={c.label} className=\"flex items-center gap-2\">\n                {i > 0 && <span aria-hidden=\"true\">/</span>}\n                {c.href ? (\n                  <Link href={c.href} className=\"underline-offset-4 hover:text-maroon hover:underline\">{c.label}</Link>\n                ) : (\n                  <span aria-current=\"page\" className=\"font-semibold text-maroon\">{c.label}</span>\n                )}\n              </li>\n            ))}\n          </ol>\n        </nav>\n\n        <h1 className=\"mt-4 font-display text-4xl font-semibold leading-tight text-maroon sm:text-5xl [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-3xl [html[lang='ta']_&]:sm:text-4xl\">{title}</h1>\n\n        {steps && current !== undefined && (\n          <ol className=\"mt-6 flex items-center gap-2 sm:gap-3\">\n            {steps.map((s, i) => {\n              const done = i < current;\n              const on = i === current;\n              return (\n                <li key={s} aria-current={on ? 'step' : undefined} className=\"flex flex-1 items-center gap-2 sm:flex-none sm:gap-3\">\n                  <span className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-sm font-bold ${on ? 'bg-maroon text-white ring-4 ring-saffron/50' : done ? 'bg-saffron text-charcoal' : 'bg-white text-charcoal/60 ring-1 ring-rose'}`}>\n                    {done ? '✓' : i + 1}\n                  </span>\n                  <span className={`hidden text-sm font-semibold sm:inline ${on ? 'text-maroon' : 'text-charcoal/70'}`}>{s}</span>\n                  {i < steps.length - 1 && <span aria-hidden=\"true\" className={`h-0.5 flex-1 sm:w-12 sm:flex-none ${done ? 'bg-saffron' : 'bg-rose'}`} />}\n                </li>\n              );\n            })}\n          </ol>\n        )}\n      </div>\n    </section>\n  );\n}\n","src/components/sevas/SevaCard.tsx":"import Link from 'next/link';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { rupees, sevaPhoto } from '@/lib/format';\nimport { txt, type Seva } from '@/data/sevas';\n\nfunction Calendar() {\n  return (\n    <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\" className=\"shrink-0\">\n      <rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2\" />\n      <path d=\"M3 10h18M8 3v4M16 3v4\" />\n    </svg>\n  );\n}\n\n// One seva in the list. The whole card opens the detail page.\nexport default function SevaCard({ seva, locale, t }: { seva: Seva; locale: Locale; t: Dictionary['sevas'] }) {\n  const name = txt(seva.name, locale);\n  const kindLabel = t.filters.find((f) => f.key === seva.kind)?.label ?? '';\n  const closed = seva.status !== 'open';\n  return (\n    <article className=\"group relative flex h-full flex-col overflow-hidden rounded-2xl bg-white shadow-md ring-2 ring-rose transition-shadow focus-within:ring-saffron hover:shadow-xl\">\n      <div className=\"relative h-40 overflow-hidden bg-maroon\">\n        <div className=\"absolute inset-0 bg-cover bg-center transition-transform duration-500 group-hover:scale-105\" style={{ backgroundImage: sevaPhoto(seva.slug) }} role=\"img\" aria-label={name} />\n        <span className=\"absolute left-3 top-3 rounded-full bg-white/95 px-3 py-1 text-xs font-bold text-maroon shadow\">{kindLabel}</span>\n      </div>\n\n      <div className=\"flex flex-1 flex-col p-5\">\n        <h3 className=\"font-display text-2xl font-semibold leading-tight text-maroon [html[lang='ta']_&]:!leading-[1.4] [html[lang='ta']_&]:text-xl\">\n          <Link href={`/${locale}/sevas/${seva.slug}`} className=\"after:absolute after:inset-0 focus-visible:outline-none\">\n            {name}\n          </Link>\n        </h3>\n        <p className=\"mt-3 flex items-center gap-2 text-sm font-semibold text-charcoal/80\">\n          <Calendar />\n          {txt(seva.when, locale)}\n        </p>\n        <p className=\"mt-4 font-display text-4xl font-semibold leading-none text-charcoal\">\n          {seva.amount > 0 ? rupees(seva.amount) : <span className=\"text-2xl text-saffron [html[lang='ta']_&]:text-xl\">{t.abilityLabel}</span>}\n        </p>\n        <p className=\"mt-auto pt-5\">\n          <span className={`inline-flex w-full items-center justify-center rounded-md px-5 py-3 text-center font-semibold transition-colors ${closed ? 'bg-rose text-charcoal/70' : 'bg-maroon text-white group-hover:bg-charcoal'}`}>\n            {closed ? t.closedLabel : t.viewLabel}\n          </span>\n        </p>\n      </div>\n    </article>\n  );\n}\n","src/components/sevas/SevaPurchase.tsx":"'use client';\n\nimport { useState } from 'react';\nimport Link from 'next/link';\nimport { useRouter } from 'next/navigation';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { WEEKDAYS, formatDate, rupees, todayISO, weekdayOf } from '@/lib/format';\nimport { dateMode, txt, type Seva } from '@/data/sevas';\nimport { useCart } from '@/components/cart/CartProvider';\n\ntype T = Dictionary['sevas'];\n\nconst inputClass =\n  'w-full rounded-md border-2 border-rose bg-white px-4 py-2.5 text-charcoal placeholder:text-charcoal/50 focus:border-saffron focus:outline-none disabled:bg-rose/50';\n\nfunction Field({ id, label, hint, error, children }: { id: string; label: string; hint?: string; error?: string; children: React.ReactNode }) {\n  return (\n    <div>\n      <label htmlFor={id} className=\"block text-sm font-bold text-charcoal\">{label}</label>\n      <div className=\"mt-1\">{children}</div>\n      {hint && !error && <p id={`${id}-hint`} className=\"mt-1 text-sm text-charcoal/70\">{hint}</p>}\n      {error && <p id={`${id}-error`} role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{error}</p>}\n    </div>\n  );\n}\n\nexport default function SevaPurchase({ seva, locale, t }: { seva: Seva; locale: Locale; t: T }) {\n  const router = useRouter();\n  const { add } = useCart();\n\n  const mode = dateMode(seva);\n  const today = todayISO();\n  const dayName = seva.weekday !== undefined ? WEEKDAYS[locale][seva.weekday] : '';\n\n  // Earliest and latest date that can be chosen\n  const minDate = mode === 'range' && seva.from && seva.from > today ? seva.from : today;\n  const maxDate = mode === 'range' ? seva.to : undefined;\n  // A one-day or ranged seva whose last date has gone by can no longer be booked\n  const past = (mode === 'fixed' || mode === 'range') && !!seva.to && seva.to < today;\n  const closed = seva.status !== 'open' || past;\n\n  const [date, setDate] = useState(mode === 'fixed' ? seva.from ?? '' : '');\n  const [devotee, setDevotee] = useState('');\n  const [gotram, setGotram] = useState('');\n  const [nakshatram, setNakshatram] = useState('');\n  const [amountStr, setAmountStr] = useState('');\n  const [qty, setQty] = useState(1);\n  const [errors, setErrors] = useState<Record<string, string>>({});\n  const [added, setAdded] = useState(false);\n\n  const choose = seva.amount === 0;\n  const unit = choose ? Number(amountStr) || 0 : seva.amount;\n  const total = unit * (choose ? 1 : qty);\n\n  const dateHelp =\n    mode === 'fixed' ? t.dateFixed.replace('{date}', formatDate(seva.from!, locale))\n    : mode === 'range' ? t.dateRange.replace('{from}', formatDate(seva.from!, locale)).replace('{to}', formatDate(seva.to!, locale))\n    : mode === 'weekday' ? t.dateWeekday.replaceAll('{day}', dayName)\n    : t.dateAny;\n\n  function validate() {\n    const e: Record<string, string> = {};\n    if (!devotee.trim()) e.devotee = t.errName;\n    if (mode !== 'fixed') {\n      if (!date) e.date = t.errDate;\n      else if (date < today) e.date = t.errDatePast;\n      else if (mode === 'range' && (date < (seva.from as string) || date > (seva.to as string))) e.date = t.errDateRange;\n      else if (mode === 'weekday' && weekdayOf(date) !== seva.weekday) e.date = t.errDateWeekday.replace('{day}', dayName);\n    }\n    if (choose && !(Number(amountStr) >= seva.minAmount)) e.amount = t.errAmount.replace('{min}', rupees(seva.minAmount));\n    setErrors(e);\n    return Object.keys(e).length === 0;\n  }\n\n  function addToCart(goToCart: boolean) {\n    if (closed || !validate()) return;\n    add({ slug: seva.slug, qty: choose ? 1 : qty, unit, date, devotee: devotee.trim(), gotram: gotram.trim(), nakshatram: nakshatram.trim() });\n    if (goToCart) router.push(`/${locale}/cart`);\n    else setAdded(true);\n  }\n\n  if (closed) {\n    return (\n      <div className=\"rounded-2xl bg-rose/60 p-6 text-center\">\n        <p className=\"font-display text-2xl font-semibold text-maroon\">{past ? t.statusPast : t.statusClosed}</p>\n        <Link href={`/${locale}/sevas`} className=\"mt-4 inline-block rounded-md bg-maroon px-5 py-2.5 font-semibold text-white hover:bg-charcoal\">{t.backLabel}</Link>\n      </div>\n    );\n  }\n\n  return (\n    <form noValidate onSubmit={(e) => { e.preventDefault(); addToCart(false); }} className=\"rounded-2xl bg-white p-6 shadow-lg ring-2 ring-rose\">\n      <h2 className=\"font-display text-2xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.4]\">{t.formTitle}</h2>\n\n      <div className=\"mt-5 space-y-4\">\n        {/* Date */}\n        <Field id=\"seva-date\" label={t.dateLabel} hint={dateHelp} error={errors.date}>\n          {mode === 'fixed' ? (\n            <p className=\"rounded-md bg-rose/50 px-4 py-2.5 font-semibold text-charcoal\">{formatDate(seva.from!, locale)}</p>\n          ) : (\n            <input id=\"seva-date\" type=\"date\" value={date} min={minDate} max={maxDate} onChange={(e) => setDate(e.target.value)}\n              aria-invalid={!!errors.date} aria-describedby={errors.date ? 'seva-date-error' : 'seva-date-hint'} className={inputClass} />\n          )}\n        </Field>\n        {seva.note && <p className=\"rounded-md bg-saffron/15 px-4 py-2 text-sm font-semibold text-charcoal\">{txt(seva.note, locale)}</p>}\n\n        {/* Devotee */}\n        <Field id=\"devotee\" label={t.devoteeName} hint={t.devoteeNameHelp} error={errors.devotee}>\n          <input id=\"devotee\" value={devotee} onChange={(e) => setDevotee(e.target.value)} autoComplete=\"off\"\n            aria-invalid={!!errors.devotee} aria-describedby={errors.devotee ? 'devotee-error' : 'devotee-hint'} className={inputClass} />\n        </Field>\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <Field id=\"gotram\" label={`${t.gotram} (${t.optional})`}>\n            <input id=\"gotram\" value={gotram} onChange={(e) => setGotram(e.target.value)} className={inputClass} />\n          </Field>\n          <Field id=\"nakshatram\" label={`${t.nakshatram} (${t.optional})`}>\n            <input id=\"nakshatram\" value={nakshatram} onChange={(e) => setNakshatram(e.target.value)} className={inputClass} />\n          </Field>\n        </div>\n\n        {/* Amount or quantity */}\n        {choose ? (\n          <Field id=\"amount\" label={t.amountInput} hint={t.amountHelp} error={errors.amount}>\n            <div className=\"relative\">\n              <span aria-hidden=\"true\" className=\"absolute left-4 top-1/2 -translate-y-1/2 font-bold text-charcoal/70\">₹</span>\n              <input id=\"amount\" inputMode=\"numeric\" value={amountStr} onChange={(e) => setAmountStr(e.target.value.replace(/\\D/g, ''))}\n                aria-invalid={!!errors.amount} aria-describedby={errors.amount ? 'amount-error' : 'amount-hint'} className={`${inputClass} pl-9`} />\n            </div>\n          </Field>\n        ) : (\n          <div>\n            <p className=\"text-sm font-bold text-charcoal\">{t.qtyLabel}</p>\n            <div className=\"mt-1 inline-flex items-center rounded-md border-2 border-rose\">\n              <button type=\"button\" aria-label=\"−\" disabled={qty <= 1} onClick={() => setQty((q) => Math.max(1, q - 1))} className=\"h-11 w-11 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">−</button>\n              <span aria-live=\"polite\" className=\"w-12 text-center text-lg font-bold\">{qty}</span>\n              <button type=\"button\" aria-label=\"+\" disabled={qty >= seva.maxQty} onClick={() => setQty((q) => Math.min(seva.maxQty, q + 1))} className=\"h-11 w-11 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">+</button>\n            </div>\n          </div>\n        )}\n      </div>\n\n      <p className=\"mt-6 flex items-baseline justify-between border-t border-rose pt-4\">\n        <span className=\"font-semibold text-charcoal/80\">{t.totalLabel}</span>\n        <span className=\"font-display text-3xl font-semibold text-maroon\">{rupees(total)}</span>\n      </p>\n\n      <div className=\"mt-4 grid gap-3 sm:grid-cols-2\">\n        <button type=\"submit\" className=\"rounded-md border-2 border-maroon px-5 py-3 font-semibold text-maroon transition-colors hover:bg-rose focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.addToCart}</button>\n        <button type=\"button\" onClick={() => addToCart(true)} className=\"rounded-md bg-maroon px-5 py-3 font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.bookNow}</button>\n      </div>\n\n      {added && (\n        <div role=\"status\" className=\"mt-4 rounded-md bg-saffron/15 px-4 py-3 text-center\">\n          <p className=\"font-semibold text-charcoal\">✓ {t.added}</p>\n          <p className=\"mt-2 flex flex-wrap justify-center gap-x-5 gap-y-1\">\n            <Link href={`/${locale}/cart`} className=\"font-bold text-maroon underline underline-offset-4\">{t.viewCart}</Link>\n            <Link href={`/${locale}/sevas`} className=\"font-bold text-maroon underline underline-offset-4\">{t.keepBrowsing}</Link>\n          </p>\n        </div>\n      )}\n    </form>\n  );\n}\n"};
